SELECT `srfuzz_mut_121`.`array_map_in_reuse_t`.`id`, CAST(1 AS BIGINT) AS `CAST(1 AS BIGINT)` FROM `srfuzz_mut_121`.`array_map_in_reuse_t` ORDER BY `srfuzz_mut_121`.`array_map_in_reuse_t`.`id` ASC;
SELECT `array_map_in_reuse_t`.`id`, CAST(1 AS BIGINT) AS `CAST(1 AS BIGINT)` FROM (SELECT `srfuzz_mut_121`.`array_map_in_reuse_t`.`id`, `srfuzz_mut_121`.`array_map_in_reuse_t`.`arr_datetime` FROM `srfuzz_mut_121`.`array_map_in_reuse_t`) `array_map_in_reuse_t` , LATERAL generate_series(1,3,1) srfuzz_n1(`e`)  WHERE array_sum(array_map(arg -> (CAST((month(`__LAMBDA_TABLE`.`__LAMBDA_TABLE`.`arg`)) AS BIGINT)) IN (1, 2), `array_map_in_reuse_t`.`arr_datetime`)) ORDER BY `array_map_in_reuse_t`.`id` ASC;